const findMatches = async (classification, teacherProfile) => {
  const teachersSnapshot = await db.collection('teachers')
    .where('gradeLevel', '==', teacherProfile.gradeLevel)
    .get();

  const potentialMatches = teachersSnapshot.docs
    .filter(doc => doc.id !== teacherProfile.id) // Avoid self-matching
    .map(doc => ({ id: doc.id, ...doc.data() }));

  const matches = await geminiAI.findBestMatches(classification, potentialMatches);
  return matches;
};

