const orchestrate = async (matches, challenge) => {
  const strategy = await geminiAI.analyzeStrategy({
    matchQuality: matches.length,
    urgency: challenge.urgency,
    complexity: challenge.classification.complexity
  });

  if (strategy.recommendAI || matches.length < 2) {
    const aiSession = await createAISession({
      challengeContext: challenge.text,
      teacherProfile: challenge.teacherProfile,
      persona: strategy.recommendedPersona
    });

    return {
      strategy: 'AI_CHAT',
      aiSession,
      aiChatRecommended: true
    };
  }

  return {
    strategy: 'PEER_SUPPORT',
    matches,
    aiChatRecommended: false
  };
};

