const classifyChallenge = async (challengeText) => {
  try {
    const geminiResponse = await geminiAI.classify(challengeText);
    return parseGeminiResponse(geminiResponse);
  } catch (error) {
    console.error('Gemini AI classification failed:', error);

    // Fallback to manual classification
    const manualClassification = {
      category: determineCategory(challengeText),
      urgency: calculateUrgency(challengeText),
      confidence: 'low'
    };

    return manualClassification;
  }
};

const determineCategory = (text) => {
  const keywords = {
    'classroom management': ['discipline', 'behavior', 'control'],
    'student engagement': ['participation', 'attention', 'motivation']
  };

  // Simple keyword matching fallback
  for (const [category, words] of Object.entries(keywords)) {
    if (words.some(word => text.toLowerCase().includes(word))) {
      return category;
    }
  }

  return 'general';
};

