const fetchPeerNames = async (peerIds) => {
  const names = {};

  for (const peerId of peerIds) {
    try {
      const teacherDoc = await getDoc(doc(db, 'teachers', peerId));
      if (teacherDoc.exists()) {
        names[peerId] = teacherDoc.data().name;
      }
    } catch (error) {
      console.error(`Error fetching name for ${peerId}:`, error);
      names[peerId] = 'Unknown Teacher';
    }
  }

  setPeerNames(names);
};

